\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}

\title{Measuring the Speed of Sound with a Resonance Tube}
\author{Lab Group 4}
\date{}

\begin{document}
\maketitle

\section{Apparatus}
\label{sec:apparatus}
The apparatus consists of a graduated glass resonance tube
partly filled with water, a set of tuning forks covering 256
to 1024 Hz, a movable piston, and a thermocouple for the air
temperature inside the tube. The full measurement sequence
is described in Section 2 of the bench manual.

\section{Procedure}
\label{sec:procedure}
The water level is lowered slowly until the first resonance
is heard, and the position of the piston is recorded. The
procedure is repeated for the second and third resonances
and for each fork in turn. The resonance positions are
analysed in Section 3.

\section{Analysis}
\label{sec:analysis}
The apparatus list in Section 1 gives the fork frequencies,
and the wavelength follows from the spacing of successive
resonances. As noted in Section~2, each recorded position is
the mean of three readings, so the standard error of the
spacing is negligible beside the calibration uncertainty of
the tube. The final estimate uses the temperature recorded
at the start of each run.

\section{Conclusion}
The measured speed agrees with the accepted value within the
combined uncertainty, and the dominant contribution remains
the reading error of the piston scale.
\end{document}

